      "تُحسب المناطق بطريقة احتياطي معدل ضربات القلب لدى Karvonen: bpm = الراحة + % × (الأقصى − الراحة). ولأن الاحتياطي — لا الأقصى — هو الذي يُقاس منه، تبقى المناطق صادقة لمن نبض راحته منخفض أو مرتفع على غير المعتاد. تعرف أقصاك المقيس من اختبار مخبري أو سباق قاسٍ؟ انتقل إلى الوضع اليدوي وأدخله مباشرة.",
