        a: "تقيس طريقة Karvonen الشدة من المسافة بين نبض راحتك وأقصى نبض، وهي الجزء الذي يعمل فعلًا. باستخدام نسبة من الأقصى مباشرة تقع منطقة 60–70% عند 112–131 bpm لمثال الثلاثيني أعلاه؛ وبنسبة من الاحتياطي عند 136–149 bpm. فسيولوجيًا يتدرّج الجهد مع مقدار الاحتياطي الذي تستخدمه، لذا تتوافق المناطق المبنية على الاحتياطي أفضل مع العتبات التنفسية والمجهود المحسوس — خاصة لمن نبض راحتهم منخفض.",
