    deepDive: [
      {
        heading: "الثنائي بايتات وليست سحراً",
        paragraphs: [
          "ما تنتجه هذه الأداة ليس «نصاً يتحول إلى 01» بعملية مجردة، بل هو تسلسل البايتات UTF-8 الذي يخزّنه الحاسوب أصلاً لنصك، معروضاً كأرقام ثنائية. الحرف «A» بايت واحد، 01000001، وهو العدد 65 — رمز ASCII الذي يعني A منذ الستينيات. لا توجد خطوة ترجمة ولا تفسير: البتات على الشاشة هي البتات في الملف.",
          "UTF-8 هو التفصيل الحاسم. محارف ASCII (الأحرف اللاتينية، الأرقام، علامات الترقيم الشائعة) تأخذ بايتاً واحداً لكل منها، فثنائيتها قصيرة. أما المحارف خارج ASCII فتأخذ بايتين إلى أربعة: «é» هي 0xC3 0xA9 (11000011 10101001)، والرمز التعبيري 😀 أربعة بايتات. لهذا تنتج الكلمة نفسها أطوالاً ثنائية مختلفة بحسب محارفها — ولهذا يكون سطر من النص الصيني أطول بنحو ثلاث مرات بالبايتات من المعنى نفسه بالإنجليزية.",
          "يفلح فك الترميز فقط إذا افترض القارئ الترميز نفسه. البايتات التي تشكّل UTF-8 صالحاً لا معنى لها بترميز EBCDIC أو Latin-1 — ظاهرة «الموجيبيكي» عند قراءة نص بترميز خاطئ هي الشكل الظاهر لفشل هذا الافتراض.",
        ],
      },
      {
        heading: "لماذا مجموعات الثمانية بتات وماذا تعني البتات الأولى",
        paragraphs: [
          "تُجمع البايتات في ثمانية لأنها وحدة المحرف العملية منذ أيام الحواسيب المركزية، وUTF-8 مصمم حولها. التسلسلات متعددة البايتات تصف نفسها ذاتياً: البايت الذي يبدأ بـ 110 يفتح محرفاً من بايتين، و1110 يفتح ثلاثة، و11110 يفتح أربعة، وبايتات الاستكمال تبدأ دائماً بـ 10. هذا التركيب سبب قدرة UTF-8 على إعادة التزامن بعد أخطاء الإرسال وسبب صياره الترميز المهيمن على الويب.",
          "قراءة بايت يدوياً: 01000001 ينقسم إلى 0 (نطاق ASCII، بايت واحد) ثم 1000001 = 65 = A. وفي 11000011 تُعلن البادئة 110 عن تسلسل من بايتين ويجب أن يبدأ البايت التالي بـ 10. حين ترى النمط يتوقف الثنائي عن كونه ضجيجاً.",
          "المسافات والأسطر وحتى اصطلاح التجميع خيارات عرض — البيانات الأساسية هي سلسلة الأرقام. بعض الأدوات تجمع بالثمانية، وبعضها بالمحرف، وبعضها يصدر تدفقاً متصلاً واحداً؛ وكلها ترمز البايتات نفسها.",
        ],
      },
      {
        heading: "حالات الاستخدام والخصوصية",
        paragraphs: [
          "الاستخدامات العملية: تدريس ترميزات المحارف وتنقيحها، والتحقق من البايتات التي سيستقبلها نمط تعبير منتظم أو واجهة برمجية فعلاً، وتوليد ألغاز ثنائية، والتحقق من الرحلة الذهاب والإياب — النص ← ثنائي ← النص يجب أن يعيد الأصل بايتاً ببايت. أي اختلاف يعني أن أحداً غيّر الترميز في الطريق.",
          "للمطورين هذه أسرع وسيلة للإجابة عن سؤال «هل هذا المحرف بايت واحد أم أربعة؟» دون فتح منقّح. وللطلاب، تحويل اسمهم ورؤية أي الحروف تبقى بايتاً واحداً وأيها يتسع يجعل UTF-8 ملموساً بما لا تفعله محاضرة.",
          "يعمل التحويل محلياً في JavaScript أثناء الكتابة — لا يُرفع شيء، ويعمل دون اتصال. النص الذي تلصقه يبقى على جهازك، سواء كان مقتطف شفرة أو مسودة رسالة.",
        ],
      },
    ],
