          "الفجوة بين «ما تراه» و«ما يُخزن» هي سبب وجود هذه الأداة. محرف يبدو واحداً — é، رمز علم، حرف صيني — قد يكون نقطة ترميز واحدة، أو نصفَي بديلين، أو حرفاً أساسياً مع علامات مركّبة. لصق النص يكشف أي الحالات أمامك، وهذا مهم حين يخطئ سكربت في عدّ الأطوال أو تقتطع قاعدة بيانات عند حدّ خاطئ.",
